using System.Collections.Generic;
using VMLAssembler;
using CompilerBase;

namespace FortranCompiler;

public partial class CodeGenerator
{
    private void GenerateStatement(ASTNode node)
    {
        switch (node)
        {
            case NopNode:
                break; // no-op (e.g., implicit none)
            case VarDeclNode decl:
                GenerateVarDecl(decl);
                break;
            case SubroutineNode sub:
                GenerateSubroutine(sub);
                break;
            case FunctionNode func:
                GenerateFunction(func);
                break;
            case CallNode call:
                GenerateCall(call);
                break;
            case ReturnNode ret:
                GenerateReturn(ret);
                break;
            case ExitNode:
                Sta!.EmitBreak();
                break;
            case CycleNode:
                Sta!.EmitContinue();
                break;
            case StopNode stop:
                if (stop.Code != null) GenerateExpression(stop.Code);
                else AddRI(OpCode.MOVE, 0, 0);
                EmitExit();
                break;
            case IfNode ifNode:
                GenerateIf(ifNode);
                break;
            case DoWhileNode doWhile:
                GenerateDoWhile(doWhile);
                break;
            case ForNode forNode:
                GenerateFor(forNode);
                break;
            case PrintNode print:
                GeneratePrint(print);
                break;
            case AssignNode assign:
                GenerateAssign(assign);
                break;
            case ArrayAssignNode aa:
                GenerateArrayAssign(aa);
                break;
            case ArraySectionNode sec:
                GenerateExpression(sec);
                break;
            case UseNode:
                // use module_name — symbols are resolved via external .vml library linking
                // (FortranCompiler.ExtractImports extracts module names for auto-link)
                break;
            case ModuleNode:
                // module body — subroutines/functions already generated by GenerateContained pass
                break;
            case AllocateNode alloc:
                GenerateAllocate(alloc);
                break;
            case DeallocateNode dealloc:
                GenerateDeallocate(dealloc);
                break;
            default:
                GenerateExpression(node);
                break;
        }
    }

    // ---- Declarations ----

    /// <summary>分配栈变量并返回偏移</summary>
    private int AllocStackSlot(string key, int size)
    {
        nextStackOffset += size;
        symbolTable[key] = nextStackOffset;
        return nextStackOffset;
    }

    private void GenerateVarDecl(VarDeclNode node)
    {
        FortranType ft = MapTypeName(node.TypeName);
        int byteSize = GetTypeInfo(ft).byteSize;
        foreach (var name in node.Names)
        {
            string key = name.ToLowerInvariant();
            _varTypes[key] = ft;
            if (!symbolTable.ContainsKey(key))
                AllocStackSlot(key, byteSize);
        }
    }

    // ---- Routines ----

    private void GenerateSubroutine(SubroutineNode node)
    {
        string funcLabel = $"sub_{node.Name.ToLowerInvariant()}";

        AddLabel(funcLabel);

        // Save old symbol table
        var savedSymbols = new Dictionary<string, int>(symbolTable);
        int savedOffset = nextStackOffset;

        // First pass: scan variable declarations to compute frame size
        int subFrameSize = 0;
        foreach (var param in node.Parameters)
        {
            nextStackOffset += 4;
            string pkey = param.ToLowerInvariant();
            symbolTable[pkey] = nextStackOffset;
            _varTypes[pkey] = FortranType.Integer;
        }
        subFrameSize = nextStackOffset;
        // Scan body for VarDecl
        void ScanDecls(List<ASTNode> body)
        {
            foreach (var s in body)
            {
                if (s is VarDeclNode vd)
                {
                    FortranType ft = MapTypeName(vd.TypeName);
                    int byteSize = GetTypeInfo(ft).byteSize;
                    foreach (var name in vd.Names)
                    {
                        string key = name.ToLowerInvariant();
                        _varTypes[key] = ft;
                        if (!symbolTable.ContainsKey(key))
                        {
                            nextStackOffset += byteSize;
                            symbolTable[key] = nextStackOffset;
                        }
                    }
                }
            }
        }
        ScanDecls(node.Body);
        subFrameSize = nextStackOffset;

        // Reset symbol table to just params
        symbolTable = new Dictionary<string, int>(savedSymbols);
        nextStackOffset = savedOffset;
        foreach (var param in node.Parameters)
        {
            nextStackOffset += 4;
            symbolTable[param.ToLowerInvariant()] = nextStackOffset;
        }

        // Function prologue + reserve stack space (+8 safety margin)
        EmitPrologueWithFrame(subFrameSize + 8);

        // Generate body
        foreach (var stmt in node.Body)
            GenerateStatement(stmt);

        // Function epilogue
        EmitEpilogue(); // 含 RET

        // Restore symbol table
        symbolTable = savedSymbols;
        nextStackOffset = savedOffset;
    }

    private void GenerateFunction(FunctionNode node)
    {
        string funcLabel = $"func_{node.Name.ToLowerInvariant()}";

        AddLabel(funcLabel);

        // Save old symbol table
        var savedSymbols = new Dictionary<string, int>(symbolTable);
        int savedOffset = nextStackOffset;

        // MemOff convention: positive offset → R12-offset (below BP), negative → R12+abs(offset) (above BP)
        // Parameters: above BP at R12+12 (saved_R12+4, saved_R15+4, ret_addr+4)
        // Return value / locals: below BP at R12-4, R12-8, ...
        int localSlot = 4; // start at R12-4
        FortranType retType = MapTypeName(node.ReturnType);

        // Allocate space for return value (function name) below BP
        string fkey = node.Name.ToLowerInvariant();
        symbolTable[fkey] = localSlot; // MemOff(4) → R12-4
        _varTypes[fkey] = retType;
        localSlot += 4;

        // Parameters are above BP
        int paramBase = -12; // MemOff(-12) → R12+12
        foreach (var param in node.Parameters)
        {
            string pkey = param.ToLowerInvariant();
            symbolTable[pkey] = paramBase; // MemOff(-12) → R12+12
            _varTypes[pkey] = FortranType.Integer;
            paramBase -= 4; // next param: -16 → R12+16
        }

        // First pass: scan body for VarDecl and allocate in localSlot
        void ScanLocalDecls(List<ASTNode> body)
        {
            foreach (var s in body)
            {
                if (s is VarDeclNode vd)
                {
                    FortranType ft = MapTypeName(vd.TypeName);
                    int byteSize = GetTypeInfo(ft).byteSize;
                    foreach (var name in vd.Names)
                    {
                        string key = name.ToLowerInvariant();
                        _varTypes[key] = ft;
                        if (!symbolTable.ContainsKey(key))
                        {
                            symbolTable[key] = localSlot;
                            localSlot += byteSize;
                        }
                    }
                }
            }
        }
        ScanLocalDecls(node.Body);

        // Function prologue + reserve stack space (+8 safety margin)
        EmitPrologueWithFrame(localSlot + 8);

        // Generate body
        foreach (var stmt in node.Body)
            GenerateStatement(stmt);

        // Load return value into R0
        EmitLoadVar(node.Name);

        // Function epilogue
        EmitEpilogue(); // 含 RET

        // Restore symbol table
        symbolTable = savedSymbols;
        nextStackOffset = savedOffset;
    }

    // ---- Statements ----

    private void GenerateCall(CallNode node)
    {
        string fname = node.Name.ToLowerInvariant();

        // Handle outint pseudo-intrinsic: SYSCALL #4 (print_int)
        if (fname == "outint")
        {
            var argType = GetExprType(node.Arguments[0]);
            GenerateExpression(node.Arguments[0]);
            if (argType == ExpType.F32)
                instructions.Add(new Instruction(OpCode.F2I, [Reg(0), Reg(0)], instructions.Count));
            else if (argType == ExpType.F64)
                instructions.Add(new Instruction(OpCode.D2I, [Reg(0), Reg(0)], instructions.Count));
            EmitPrintChar();
            return;
        }

        // Handle print_int/x for array operations — extract argument type and use SYSCALL
        bool isSyscallInt = fname == "print_int" || fname == "out_int";
        if (isSyscallInt)
        {
            GenerateExpression(node.Arguments[0]);
            EmitPrintChar();
            return;
        }

        // Push arguments in reverse order
        for (int i = node.Arguments.Count - 1; i >= 0; i--)
        {
            GenerateExpression(node.Arguments[i]);
            instructions.Add(new Instruction(OpCode.PUSH,
                new List<Operand> { new Operand(OperandType.REGISTER, 0) }, instructions.Count));
        }

        string funcLabel = $"sub_{fname}";
        instructions.Add(new Instruction(OpCode.CALL,
            new List<Operand> { new Operand(OperandType.LABEL, funcLabel) }, instructions.Count));

        // Pop arguments
        for (int i = 0; i < node.Arguments.Count; i++)
            instructions.Add(new Instruction(OpCode.POP,
                new List<Operand> { new Operand(OperandType.REGISTER, 1) }, instructions.Count));
    }

    private void GenerateReturn(ReturnNode node)
    {
        EmitEpilogue(); // 含 RET
    }

    private void GenerateIf(IfNode node)
    {
        Sta!.EmitIf(
            emitCondition: () => GenerateExpression(node.Condition),
            emitThen: () => { foreach (var stmt in node.ThenBody) GenerateStatement(stmt); },
            emitElse: node.ElseBody != null ? () => { foreach (var stmt in node.ElseBody) GenerateStatement(stmt); } : null);
    }

    private void GenerateDoWhile(DoWhileNode node)
    {
        Sta!.EmitWhile(
            emitCondition: () => GenerateExpression(node.Condition),
            emitBody: () => { foreach (var stmt in node.Body) GenerateStatement(stmt); });
    }

    private void GenerateFor(ForNode node)
    {
        // do var = start, end [, step]
        // Init var = start
        GenerateExpression(node.Start);
        EmitStoreVar(node.Var);

        string startLabel = $"do_{labelCounter++}";
        string endLabel = $"enddo_{labelCounter++}";

        Sta!.PushLoopLabels(endLabel, startLabel);
        AddLabel(startLabel);

        // Check var <= end
        EmitLoadVar(node.Var);
        instructions.Add(new Instruction(OpCode.PUSH,
            new List<Operand> { new Operand(OperandType.REGISTER, 0) }, instructions.Count));
        GenerateExpression(node.End);
        instructions.Add(new Instruction(OpCode.POP,
            new List<Operand> { new Operand(OperandType.REGISTER, 1) }, instructions.Count));
        instructions.Add(new Instruction(OpCode.CMP,
            new List<Operand> { new Operand(OperandType.REGISTER, 1), new Operand(OperandType.REGISTER, 0) },
            instructions.Count));
        instructions.Add(new Instruction(OpCode.JG,
            new List<Operand> { new Operand(OperandType.LABEL, endLabel) }, instructions.Count));

        // Loop body
        foreach (var stmt in node.Body)
            GenerateStatement(stmt);

        // var += step (default 1)
        EmitLoadVar(node.Var);
        int stepVal = 1;
        if (node.Step != null && node.Step is LiteralNode lit && lit.Value is int si)
            stepVal = si;
        instructions.Add(new Instruction(OpCode.ADD,
            new List<Operand> { new Operand(OperandType.REGISTER, 0), new Operand(OperandType.REGISTER, 0), new Operand(OperandType.IMMEDIATE, stepVal) },
            instructions.Count));
        EmitStoreVar(node.Var);

        instructions.Add(new Instruction(OpCode.JMP,
            new List<Operand> { new Operand(OperandType.LABEL, startLabel) }, instructions.Count));

        AddLabel(endLabel);
        Sta!.PopLoopLabels();
    }

    private void GeneratePrint(PrintNode node)
    {
        // Distinguish read vs print using the IsRead flag
        if (node.IsRead)
        {
            // read(*,*) var1, var2, ... — read integer into each variable
            foreach (var expr in node.Expressions)
            {
                if (expr is VarNode vn)
                {
                    EmitInputInt(); // SYSCALL #7: input_int → R0
                    EmitStoreVar(vn.Name);
                }
            }
            return;
        }

        EmitPrintArgs(node.Expressions.Count,
            i => GenerateExpression(node.Expressions[i]),
            i => node.Expressions[i] is LiteralNode lit && lit.Value is string
                || (node.Expressions[i] is CallNode call && IsStringReturningFunc(call.Name))
                || (node.Expressions[i] is FuncCallNode fcall && IsStringReturningFunc(fcall.Name)));
    }

    private void GenerateAllocate(AllocateNode node)
    {
        // allocate(array(size)) → array = malloc((size+1)*4); array[0] = size
        GenerateExpression(node.Size);                          // R0 = size
        instructions.Add(new Instruction(OpCode.ADD,
            [new Operand(OperandType.REGISTER, 0), new Operand(OperandType.REGISTER, 0), new Operand(OperandType.IMMEDIATE, 1)]));
        instructions.Add(new Instruction(OpCode.MUL,
            [new Operand(OperandType.REGISTER, 0), new Operand(OperandType.REGISTER, 0), new Operand(OperandType.IMMEDIATE, 4)]));
        EmitAlloc();          // malloc
        // Store size at array[0]
        instructions.Add(new Instruction(OpCode.MOVE,
            [new Operand(OperandType.REGISTER, 1), new Operand(OperandType.REGISTER, 0)]));
        GenerateExpression(node.Size);
        instructions.Add(new Instruction(OpCode.MOVE,
            [new Operand(OperandType.MEMORY, "R1"), new Operand(OperandType.REGISTER, 0)]));
        instructions.Add(new Instruction(OpCode.MOVE,
            [new Operand(OperandType.REGISTER, 0), new Operand(OperandType.REGISTER, 1)]));
        EmitStoreVar(node.Name);
    }

    private void GenerateDeallocate(DeallocateNode node)
    {
        // deallocate(array) → free(array)
        EmitLoadVar(node.Name);
        instructions.Add(new Instruction(OpCode.SYSCALL,
            [new Operand(OperandType.IMMEDIATE, 41)]));          // free
    }

    private void GenerateAssign(AssignNode node)
    {
        // 数组元素赋值: a(i) = expr
        if (node.ArrayIndices != null && node.ArrayIndices.Count > 0)
        {
            string key = node.Name.ToLowerInvariant();
            // 保存值到栈
            GenerateExpression(node.Value);
            instructions.Add(new Instruction(OpCode.PUSH,
                new List<Operand> { new Operand(OperandType.REGISTER, 0) }, instructions.Count));
            // 计算数组基地址到 R1
            if (symbolTable.TryGetValue(key, out int offset))
                instructions.Add(new Instruction(OpCode.MOVE,
                    new List<Operand> { new Operand(OperandType.REGISTER, 1), new Operand(OperandType.MEMORY, $"R12+{offset}") },
                    instructions.Count));
            else
                instructions.Add(new Instruction(OpCode.MOVE,
                    new List<Operand> { new Operand(OperandType.REGISTER, 1), new Operand(OperandType.LABEL, $"var_{key}") },
                    instructions.Count));
            // 计算索引偏移 (Fortran 1-based: index-1, 乘以4字节)
            GenerateExpression(node.ArrayIndices[0]);
            AddRI(OpCode.SUB, 0, 1);
            AddRI(OpCode.MUL, 0, 4);
            instructions.Add(new Instruction(OpCode.ADD,
                new List<Operand> { new Operand(OperandType.REGISTER, 1), new Operand(OperandType.REGISTER, 0) },
                instructions.Count));
            // 恢复R0值并存储到计算地址
            instructions.Add(new Instruction(OpCode.POP,
                new List<Operand> { new Operand(OperandType.REGISTER, 0) }, instructions.Count));
            instructions.Add(new Instruction(OpCode.MOVE,
                new List<Operand> { new Operand(OperandType.MEMORY, "R1"), new Operand(OperandType.REGISTER, 0) },
                instructions.Count));
            return;
        }
        GenerateExpression(node.Value);
        EmitStoreVar(node.Name);
    }

    /// MCU-compatible array section assignment: A(:) = B(:) + C(:) → do i=1,n; A(i)=B(i)+C(i); end do
    private void GenerateArrayAssign(ArrayAssignNode node)
    {
        string idxVar = $"__i_{node.Target}";
        int n = _arraySizes.TryGetValue(node.Target, out int size) ? size : 10;

        // do idxVar = 1, n
        string loopStart = NewLabel($"__arr_{node.Target}");
        string loopEnd = NewLabel($"__arr_end_{node.Target}");

        // init: idxVar = 1
        if (!symbolTable.ContainsKey(idxVar))
        {
            nextStackOffset += 4;
            symbolTable[idxVar] = nextStackOffset;
        }
        instructions.Add(new Instruction(OpCode.MOVE, [new Operand(OperandType.REGISTER, 0), new Operand(OperandType.IMMEDIATE, 1)]));
        EmitStoreVar(idxVar);

        // Loop start
        AddLabel(loopStart);
        // condition: idxVar <= n
        EmitLoadVar(idxVar);
        instructions.Add(new Instruction(OpCode.PUSH, [new Operand(OperandType.REGISTER, 0)]));
        instructions.Add(new Instruction(OpCode.MOVE, [new Operand(OperandType.REGISTER, 0), new Operand(OperandType.IMMEDIATE, n)]));
        instructions.Add(new Instruction(OpCode.POP, [new Operand(OperandType.REGISTER, 1)]));
        instructions.Add(new Instruction(OpCode.CMP, [new Operand(OperandType.REGISTER, 1), new Operand(OperandType.REGISTER, 0)]));
        instructions.Add(new Instruction(OpCode.JG, [new Operand(OperandType.LABEL, loopEnd)]));

        // Body: A(i) = B(i) + C(i)
        // Compute B(i) + C(i)
        GenerateArrayElem(node.LeftArr, idxVar);
        instructions.Add(new Instruction(OpCode.PUSH, [new Operand(OperandType.REGISTER, 0)]));
        GenerateArrayElem(node.RightArr, idxVar);
        instructions.Add(new Instruction(OpCode.POP, [new Operand(OperandType.REGISTER, 1)]));
        instructions.Add(new Instruction(OpCode.ADD, [new Operand(OperandType.REGISTER, 0), new Operand(OperandType.REGISTER, 1), new Operand(OperandType.REGISTER, 0)]));
        // Store to A(i)
        var arrAddr = GetArrayAddrReg();
        GenerateArrayElemAddr(node.Target, idxVar);
        instructions.Add(new Instruction(OpCode.MOVE, [new Operand(OperandType.MEMORY, "R1"), new Operand(OperandType.REGISTER, 0)]));

        // idxVar++
        EmitLoadVar(idxVar);
        instructions.Add(new Instruction(OpCode.ADD, [new Operand(OperandType.REGISTER, 0), new Operand(OperandType.IMMEDIATE, 1)]));
        EmitStoreVar(idxVar);
        instructions.Add(new Instruction(OpCode.JMP, [new Operand(OperandType.LABEL, loopStart)]));
        AddLabel(loopEnd);
    }

    private void GenerateArrayElem(ASTNode arr, string idx)
    {
        if (arr is ArraySectionNode sec)
        {
            GenerateArrayElemAddr(sec.Name, idx);
            instructions.Add(new Instruction(OpCode.MOVE, [new Operand(OperandType.REGISTER, 0), new Operand(OperandType.MEMORY, "R0")]));
        }
        else
        {
            GenerateExpression(arr);
        }
    }

    private int GetArrayAddrReg() => 1;

    private void GenerateArrayElemAddr(string name, string idx)
    {
        // R0 = base address of array 'name'
        instructions.Add(new Instruction(OpCode.MOVE, [new Operand(OperandType.REGISTER, 0), new Operand(OperandType.MEMORY, "_arr_" + name)]));
        // R1 = index value
        EmitLoadVar(idx);
        instructions.Add(new Instruction(OpCode.SUB, [new Operand(OperandType.REGISTER, 1), new Operand(OperandType.IMMEDIATE, 1)])); // Fortran 1-based to 0-based
        instructions.Add(new Instruction(OpCode.MUL, [new Operand(OperandType.REGISTER, 1), new Operand(OperandType.IMMEDIATE, 4)]));  // * elemSize
        instructions.Add(new Instruction(OpCode.ADD, [new Operand(OperandType.REGISTER, 0), new Operand(OperandType.REGISTER, 1)])); // addr = base + idx*4
    }
}
